import CustomizedButton from "components/common/CustomizedButton";
import useFetchData from "hooks/useFetchData";
import React, { useEffect, useState } from "react";
import { Button, Card, Form, Container, Row, Col } from "react-bootstrap";
import { useHistory, useParams } from "react-router";
import { axios } from "utility/httpreq";
const defaultForm = {
  title: "",
  subtitle: "",
  cardBody: "",
  body: "",
  email: "",
  thumbnail: "",
  youtubeVideoId: "",
};
const BlogEdit = () => {
  const params = useParams();
  const history = useHistory();
  const [loading, setLoading] = useState(false);
  const [info, setInfo] = useState(defaultForm);
  useFetchDataWithStateMangement(`/api/blog/${params.id}`, setInfo)

  const [file, setFile] = useState(null);
  // useEffect(() => {
  //   (async () => {
  //     const res = await axios(true).get(`/api/blog/${params.id}`);
  //     if (res.data && res.data.data) {
  //       const blog = res.data.data;
  //       setInfo({
  //         title: blog?.title,
  //         subtitle: blog?.subtitle,
  //         cardBody: blog?.cardBody,
  //         body: blog?.body,
  //         thumbnail: blog?.thumbnail,
  //         youtubeVideoId: blog?.youtubeVideoId,
  //       });
  //     }
  //   })();
  // }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const formData = new FormData();

    for (let key in info) {
      if (key == "thumbnail") {
        if (!file) continue;
        formData.append(key, file);
      } else {
        formData.append(key, info[key]);
      }
    }
    try {
      await axios(true).put("/api/blog/update/" + params.id, formData);
      history.push("/admin/blogs");
    } catch (error) {
      console.log("error is", error);
    }
  };
  const handleChange = (e) => {
    const { name, value, type, files } = e.target;
    if (type === "file") {
      return setFile(files[0]);
    }
    setInfo({ ...info, [name]: value });
  };
  return (
    <>
      <Container fluid>
        <Row>
          <Col md="8">
            <Card>
              <Card.Header>
                <Card.Title as="h4"> Edit Blog</Card.Title>
              </Card.Header>
              <Card.Body>
                <Form onSubmit={handleSubmit}>
                  <Row>
                    <Col className="pr-1" md="12">
                      <Form.Group>
                        <label>Title</label>
                        <Form.Control
                          placeholder="Title"
                          type="text"
                          name="title"
                          value={info?.title}
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                  </Row>

                  <Row>
                    <Col className="pl-1" md="12">
                      <Form.Group>
                        <label>Sub title</label>
                        <Form.Control
                          placeholder="Subtitle"
                          type="text"
                          name="subtitle"
                          value={info?.subtitle}
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                  </Row>

                  <Row>
                    <Col className="pl-1" md="12">
                      <Form.Group>
                        <label>Video Url</label>
                        <Form.Control
                          placeholder="Your video url"
                          type="text"
                          name="youtubeVideoId"
                          value={info?.youtubeVideoId}
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                  </Row>

                  <Row>
                    <Col className="pr-1" md="12">
                      <Form.Group>
                        <label htmlFor="shortDescription">
                          Short Description
                        </label>
                        <textarea
                          className="form-control form-control-flush mb-3"
                          rows="2"
                          id="shortDescription"
                          name="cardBody"
                          value={info?.cardBody}
                          onChange={handleChange}
                          placeholder="Short Description"
                          spellCheck="false"
                        ></textarea>
                      </Form.Group>
                    </Col>
                  </Row>

                  <Row>
                    <Col className="pr-1" md="12">
                      <Form.Group>
                        <label htmlFor="longDescription">
                          Long Description
                        </label>
                        <textarea
                          className="form-control form-control-flush mb-3"
                          rows="2"
                          name="body"
                          value={info?.body}
                          onChange={handleChange}
                          placeholder="Long Description"
                          id="longDescription"
                          spellCheck="false"
                        >
                          {info?.body}
                        </textarea>
                      </Form.Group>
                    </Col>
                  </Row>

                  <Row>
                    <Col className="pr-1" md="12">
                      <Form.Group>
                        <label htmlFor="longDescription">Thumbnail</label>
                        <Form.Control
                          type="file"
                          name="thumbnail"
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                  </Row>

                  {info && info.thumbnail && !file ? (
                    <Row className="mt-3">
                      <Col className="pr-1" md="12">
                        <figure>
                          <img
                            src={`${process.env.REACT_APP_BASE_URL}${info?.thumbnail?.url}`}
                            className="img-fluid"
                            alt={info?.thumbnail.name}
                          />
                        </figure>
                      </Col>
                    </Row>
                  ) : (
                    file && (
                      <Row className="mt-3">
                        <Col className="pr-1" md="12">
                          <figure>
                            <img
                              src={URL.createObjectURL(file || {})}
                              className="img-fluid"
                              alt={file?.name}
                            />
                          </figure>
                        </Col>
                      </Row>
                    )
                  )}

                  <Row>
                    <Col className="pr-1" md="12">
                      <iframe
                        width="560"
                        height="315"
                        src={`https://www.youtube.com/embed/${
                          info?.youtubeVideoId || ""
                        }`}
                        title="YouTube video player"
                        frameborder="0"
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                        allowfullscreen
                      ></iframe>
                    </Col>
                  </Row>

                  <Row className="mt-3">
                    <Col className="pr-1" md="12">
                      {/* <Button
                        className="btn-fill pull-right"
                        type="submit"
                        variant="info"
                      >
                        Submit
                      </Button> */}
                      <CustomizedButton
                        isDisabled={loading}
                        classNames="btn-fill pull-right"
                      />
                    </Col>
                  </Row>

                  <div className="clearfix"></div>
                </Form>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );
};

export default BlogEdit;

const useFetchDataWithStateMangement= (url,setInfo ) => {
  useEffect(( ) => {
    (async () => {
      const res = await axios(true).get(url);
      if (res.data && res.data.data) {
        const blog = res.data.data;
        setInfo({
          title: blog?.title,
          subtitle: blog?.subtitle,
          cardBody: blog?.cardBody,
          body: blog?.body,
          thumbnail: blog?.thumbnail,
          youtubeVideoId: blog?.youtubeVideoId,
        });
      }
    })();
  }, [])
}