import CustomizedButton from "components/common/CustomizedButton";
import React, { useEffect, useState } from "react";

import { Card, Form, Container, Row, Col } from "react-bootstrap";
import { useHistory } from "react-router";
import auth from "utility/auth";
import { axios } from "utility/httpreq";
import notify from "utility/notify";

const AddRole = () => {
  const user = JSON.parse(localStorage.getItem("loggedInUser"));
  const history = useHistory();
  const [isLogging, setIsLogging] = useState(false);
  const [permissions, setPermissions] = useState([]);
  const [formData, setFormData] = useState({
    name: "",
    permission: [],
  });

  useEffect(() => {
    const runAsync = async function () {
      try {
        const response = await axios(true).get("/api/permission/list");
        setPermissions(response.data);
      } catch (err) {
        console.log("err", err);
      }
    };
    runAsync();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      setIsLogging(true);
      await axios(true).post("/api/role/add", formData);
      setIsLogging(false);
      history.push("/admin/roles");
      notify.showSuccess("Role added successfully");
    } catch (error) {
      setIsLogging(false);
      notify.showError(error.response);
    }
  };
  const handleChange = (e) => {
    const { name, value, type } = e.target;

    if (type == "checkbox") {
      setFormData({ ...formData, permission: [...formData.permission, value] });
      console.log(formData.permission)
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

  let content = (
    <>
      <Container fluid>
        <Row>
          <Col md="8">
            <Card>
              <Card.Header>
                <Card.Title as="h4"> Add Role</Card.Title>
              </Card.Header>
              <Card.Body>
                <Form onSubmit={handleSubmit}>
                  <Row>
                    <Col className="pr-1" md="12">
                      <Form.Group>
                        <label>Role Name</label>
                        <Form.Control
                          placeholder="role name"
                          type="text"
                          name="name"
                          value={formData.name}
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                  </Row>
                  <Row>
                    {permissions &&
                      permissions.map((per, index) => {
                        return (
                          <Col key={index} className="pl-5" md="4">
                            <Form.Group>
                              <Form.Check
                                onChange={handleChange}
                                value={per._id}
                                name="permission"
                                aria-label="option 1"
                                id={per._id}
                              />
                              <label htmlFor={per._id} >{per.name}</label>
                            </Form.Group>
                          </Col>
                        );
                      })}
                  </Row>
                  <Row className="mt-3">
                    <Col className="pr-1" md="12">
                      {/* <Button
                        className="btn-fill pull-right"
                        type="submit"
                        variant="info"
                      >
                        Submit
                      </Button> */}
                      <CustomizedButton
                        isDisabled={isLogging}
                        classNames="btn-fill pull-right"
                      />
                    </Col>
                  </Row>

                  <div className="clearfix"></div>
                </Form>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );

  if (auth(user)?.isRole("Admin")) {
    return content;
  } else {
    return <Redirect to="/admin/dashboard" />;
  }
};

export default AddRole;
